import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

custom_code = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Fused scale + batchnorm kernel
__global__ void fused_scale_bn_kernel(
    const float* input,
    const float* scale,
    const float* bias,
    float* output,
    int num_elements,
    int channels,
    int spatial_size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;
    int c = (idx / spatial_size) % channels;
    output[idx] = input[idx] * scale[c] + bias[c];
}

torch::Tensor fused_scale_bn_cuda(
    torch::Tensor input,
    torch::Tensor scale,
    torch::Tensor bias
) {
    int batch_size = input.size(0);
    int channels = input.size(1);
    int spatial_size = input.size(2) * input.size(3) * input.size(4);
    int num_elements = batch_size * channels * spatial_size;

    auto output = torch::zeros_like(input);
    const int block_size = 256;
    const int num_blocks = (num_elements + block_size - 1) / block_size;

    fused_scale_bn_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        scale.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        channels,
        spatial_size
    );

    return output;
}

// Optimized global average pooling
__global__ void global_avg_pool_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int spatial_size
) {
    extern __shared__ float shared[];

    int n = blockIdx.x;
    int c = blockIdx.y;
    int tid = threadIdx.x;

    float sum = 0.0f;
    for (int i = tid; i < spatial_size; i += blockDim.x) {
        sum += input[n * channels * spatial_size + c * spatial_size + i];
    }

    shared[tid] = sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shared[tid] += shared[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        output[n * channels + c] = shared[0] / spatial_size;
    }
}

torch::Tensor global_avg_pool_cuda(torch::Tensor input) {
    int batch_size = input.size(0);
    int channels = input.size(1);
    int spatial_size = input.size(2) * input.size(3) * input.size(4);

    auto output = torch::zeros({batch_size, channels, 1, 1, 1}, input.options());
    dim3 grid(batch_size, channels);
    int block_size = 256;
    size_t shared_size = block_size * sizeof(float);

    global_avg_pool_kernel<<<grid, block_size, shared_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        spatial_size
    );

    return output;
}
"""

cpp_wrapper = """
torch::Tensor fused_scale_bn_cuda(torch::Tensor input, torch::Tensor scale, torch::Tensor bias);
torch::Tensor global_avg_pool_cuda(torch::Tensor input);
"""

custom_ops = load_inline(
    name='custom_ops',
    cpp_sources=cpp_wrapper,
    cuda_sources=custom_code,
    functions=['fused_scale_bn_cuda', 'global_avg_pool_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scale_factor, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size)
        self.scale_factor = scale_factor
        self.batch_norm = nn.BatchNorm3d(out_channels, eps=eps, momentum=momentum)
        self.fused_scale_bn = custom_ops.fused_scale_bn_cuda
        self.global_pool = custom_ops.global_avg_pool_cuda

    def forward(self, x):
        x = self.conv_transpose(x)
        scale = self.scale_factor * self.batch_norm.weight / torch.sqrt(self.batch_norm.running_var + self.batch_norm.eps)
        bias = self.batch_norm.bias - self.batch_norm.running_mean * scale
        x = self.fused_scale_bn(x, scale, bias)
        x = self.global_pool(x)
        return x
